#include<bits/stdc++.h>
#define int long long
using namespace std;
int n,m;
int a[111][111];
int ans=0;
vector<int>ansv;
void dfs(int d,int p,int sum,vector<int>&v) {
	if(p==n){
		v.push_back(d);
		if (sum>ans){
			ansv=v;
			ans=sum;
		}
		v.pop_back();
		return ;
	}else{
		for(int i=d+1;i<=m;i++){
			v.push_back(d);
			dfs(i,p+1,sum+a[p+1][i],v);
			v.pop_back();
		}
	}
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	cin>>n>>m;
	for(int i=1;i<=n;i++){
		for(int j=1;j<=m;j++){
			cin>>a[i][j];
		}
	}
	vector<int>v;
	dfs(0,0,0,v);
	cout<<ans<<endl;
	for(int i=1;i<ansv.size();i++){
		cout<<ansv[i]<<" ";
	}
	return 0;
}
